#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
int distance[3][3]={{0,2,4},{2,0,3},{4,3,0}},n=3;
int dp[8][3];for(int mask=0;mask<8;mask++)for(int j=0;j<3;j++)dp[mask][j]=1000000;
