for(int mask=1;mask<(1<<n);mask++)
    for(int last=0;last<n;last++)if(dp[mask][last]<1000000)
        for(int next=0;next<n;next++)if(!(mask&(1<<next)))
            dp[mask|(1<<next)][next]=min(dp[mask|(1<<next)][next],dp[mask][last]+distance[last][next]);
int best=1000000;
for(int last=1;last<n;last++)best=min(best,dp[(1<<n)-1][last]+distance[last][0]);
cout<<"shortest tour "<<best<<"
";
return 0;
}

