#include <cmath>
#include <algorithm>
#include <iomanip>
#include <set>
using namespace std;

int main(){
vector<set<int>>sets={{0,1,2},{2,3},{3,4,5},{0,4}};
set<int>uncovered={0,1,2,3,4,5};vector<int>chosen;
while(!uncovered.empty()){
    int best=-1,covered=0;
    for(int i=0;i<int(sets.size());i++){
        int gain=0;for(int x:sets[i])if(uncovered.count(x))gain++;
        if(gain>covered){covered=gain;best=i;}
    }
    if(best<0)break;
    chosen.push_back(best);
    for(int x:sets[best])uncovered.erase(x);
}
for(int index:chosen)cout<<index<<" ";cout<<"
";
return 0;
}

